const chat=$("#chat"),chatB=$("#chatB");let greeted=false;
function addMsg(who,text,action){const d=document.createElement("div");d.className="msg "+who;d.textContent=text;
  if(action){const b=document.createElement("button");b.className="mact";b.innerHTML=esc(action.label)+" "+SV.arrow.replace('width','data-w');b.querySelector("svg").style.width="16px";b.onclick=()=>{closeChat();runAction(action.target)};d.appendChild(document.createElement("br"));d.appendChild(b)}
  chatB.appendChild(d);chatB.scrollTop=chatB.scrollHeight}
function runAction(t){if(t==="journey"){$("#kjourney").scrollIntoView({behavior:"smooth"})}else if(t.startsWith("stop:")){$("#kjourney").scrollIntoView({behavior:"smooth"});setTimeout(()=>goTo(+t.split(":")[1]),500)}}
function kukuaReply(text,action){const t=document.createElement("div");t.className="msg k typing";t.innerHTML="<i></i><i></i><i></i>";chatB.appendChild(t);chatB.scrollTop=chatB.scrollHeight;
  setTimeout(()=>{t.remove();addMsg("k",text,action);if(V.enabled&&!V.muted)speakText(text)},reduced?0:750)}
function answer(q){const words=q.toLowerCase().replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(w=>w.length>2);
  let best=null,bs=0;LISTS.FAQs.forEach(f=>{const kw=(f.Keywords+" "+f.Question).toLowerCase();let s=0;words.forEach(w=>{if(kw.includes(w))s++});if(f.Question.toLowerCase()===q.toLowerCase())s+=10;if(s>bs){bs=s;best=f}});
  if(best&&bs>=1)kukuaReply(best.Answer,best.ActionTarget?{label:best.ActionLabel,target:best.ActionTarget}:null);else kukuaReply(msg("chatFallback").Text)}
function ask(q){addMsg("u",q);answer(q)}
