$("#chatF").addEventListener("submit",e=>{e.preventDefault();const v=$("#chatIn").value.trim();if(!v)return;$("#chatIn").value="";ask(v)});
function openChat(){chat.classList.add("open");$("#fab").style.visibility="hidden";if(!greeted){greeted=true;kukuaReply(msg("chatGreeting").Text)}setTimeout(()=>$("#chatIn").focus(),300)}
function closeChat(){chat.classList.remove("open");$("#fab").style.visibility="";$("#fab").focus()}
document.addEventListener("click",e=>{if(e.target.closest("[data-open-chat]"))openChat()});
