function countUp(el){const to=+el.dataset.to,t0=performance.now(),dur=reduced?1:1700;const f=t=>{const p=Math.min(1,(t-t0)/dur);el.textContent=Math.round(to*(1-Math.pow(1-p,3))).toLocaleString();if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
new IntersectionObserver((es,o)=>es.forEach(e=>{if(e.isIntersecting){o.disconnect();$$("#hlGrid .count").forEach(countUp);$$("#hlGrid .minibar i").forEach(b=>b.style.width=b.dataset.w+"%")}}),{threshold:.3}).observe($("#hlGrid"));

